#!/usr/bin/env python3
"""Generate static portfolio views. Edit this source, then regenerate. No runtime framework."""
from pathlib import Path
from html import escape
import re
ROOT=Path(__file__).resolve().parents[1]
BASE='https://ciarramazaredo.vercel.app'
EMAIL='ciarramazaredo@gmail.com'
nav=[('/case-studies','Work'),('/roles','Roles'),('/industries','Industries'),('/workflows','Workflows'),('/ai-sprint','AI Sprint'),('/test-me','Test me'),('/contact','Contact')]
def header(route):
 return '<a class="skip-link" href="#main">Skip to content</a><header><div class="nav-wrap"><a href="/" class="logo">ciarra<span class="dot">.</span>mazaredo</a><nav aria-label="Primary"><ul id="nav-menu">'+''.join(f'<li><a href="{url}"'+(' aria-current="page"' if url==route else '')+f'>{label}</a></li>' for url,label in nav)+'</ul></nav><a class="nav-cta" href="/resume">Résumé</a><button type="button" class="nav-toggle" aria-expanded="false" aria-controls="nav-menu">Menu</button></div></header>'
def page(route,title,description,body):
 doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} · Ciarra Mazaredo</title><meta name="description" content="{escape(description,quote=True)}">
<link rel="canonical" href="{BASE}{route}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta name="theme-color" content="#5B3FE9">
<meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{BASE}{route}"><meta property="og:type" content="website"><meta property="og:image" content="{BASE}/assets/img/og.jpg">
<script>document.documentElement.classList.add('js');</script><script src="/assets/site-config.js"></script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;family=Space+Grotesk:wght@500;600;700&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/portfolio.css">
</head><body>{header(route)}<main id="main">{body}</main><footer><div class="footer-inner"><span>© 2026 Ciarra Amor G. Mazaredo · Philippines</span><a href="/contact">Employment and project inquiries</a><a href="/ai-notes">Applied AI notes</a><a href="https://www.linkedin.com/in/ciarra-m/" rel="noopener">LinkedIn</a></div></footer><script src="/assets/site.js"></script><script src="/assets/portfolio.js"></script></body></html>'''
 dest=ROOT/(route.lstrip('/')+'.html');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
def hero(kicker,title,sub,extra=''):
 return f'<section class="hero"><div class="container"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="sub">{sub}</p>{extra}</div></section>'
def section(title,body,id=''):
 return f'<section class="content-section"'+(f' id="{id}"' if id else '')+f'><div class="container"><h2>{title}</h2>{body}</div></section>'
def cards(items):
 return '<div class="offer-grid">'+''.join(f'<article class="offer-card"><h3>{t}</h3><p>{p}</p><a class="text-link" href="{u}">{l} →</a></article>' for t,p,u,l in items)+'</div>'
def list_(items):return '<ul class="plain-list">'+''.join(f'<li>{x}</li>' for x in items)+'</ul>'
def cta():return '<div class="actions"><a class="btn btn-primary" href="/contact?intent=employment">Discuss a role</a><a class="btn" href="/ai-sprint">Explore a workflow project</a></div>'
roles=[
 ('chief-of-staff','Chief of Staff','Turning leadership priorities into coordinated work.', 'My senior management experience connects people, reporting, and cross-functional follow-through.', ['Prepare decision briefs with clear owners and next steps.','Coordinate priorities, deadlines, and stakeholder communication.','Build an operating cadence that makes unresolved work visible.'], 'edgyvis-people-ops','People operations and leadership'),
 ('operations-manager','Operations Manager','Make recurring work easier to run.', 'I document processes, coordinate people, and connect reporting to the work that needs attention.', ['Define responsibilities, handoffs, and escalation paths.','Create onboarding materials and practical operating procedures.','Track commitments and improve recurring reporting.'], 'yokly-onboarding','Onboarding and training'),
 ('executive-assistant','Executive Assistant to CEO','Protect attention and keep commitments moving.', 'My executive support experience includes correspondence, scheduling, and coordination around real estate work.', ['Prepare meetings, correspondence, and follow-up.','Keep calendars and changing priorities organized.','Use AI-assisted drafts with human review and discretion.'], 'yokly-onboarding','Real estate executive support'),
 ('marketing-operations','Marketing Operations Specialist','Connect content, campaigns, and follow-through.', 'My work spans real estate email sequences, content assets, and structured publishing workflows.', ['Map lifecycle communications and CRM handoffs.','Coordinate approved content across calendars.','Document reporting definitions before interpreting results.'], 'email-funnel','Email and lifecycle operations'),
 ('ai-automation','AI Automation Specialist','Build workflows around real business rules.', 'Explore code samples, offline tests, and clear limits on what has been validated.', ['Map the process before selecting tools.','Separate calculations, AI drafts, and approval decisions.','Test missing inputs, exceptions, and handover needs.'], 'content-routing','Content workflow case study')]
for slug,label,headline,intro,bullets,case,label2 in roles:
 page('/roles/'+slug,label,intro,hero('Employment · '+label,headline,intro)+section('What I bring to this role',list_(bullets))+section('Explore the work behind it',cards([(label2,'See my contribution, process, and evidence limits.','/case-studies/'+case,'Read the case study'),('Workflow examples','Inspect sample code and its tested scope.','/workflows','Browse workflows')]))+section('Discuss the right working arrangement','<p>Based in the Philippines. Open to global remote employment and separately scoped projects.</p><p>Hours, responsibilities, and compensation are agreed for the role.</p>'+cta()))
page('/roles','Roles','Five views of operations, executive support, marketing, and AI workflow experience.',hero('Employment','One background, five useful perspectives.','Explore the experience most relevant to your team. Target roles are separate from my historical job titles.')+section('Choose the role you need',cards([(r[1],r[3],'/roles/'+r[0],'Explore this role') for r in roles]))+section('Experience with a clear context','<p>My background includes school leadership, executive support, real estate marketing, and workflow development.</p><p><a class="text-link" href="/test-me">Explore the hiring kit</a> · <a class="text-link" href="/how-i-work">Read how I work</a></p>'+cta()))
industries=[
 ('real-estate','Real estate and property operations','Keep property work moving between people.','My real estate marketing and executive support experience is directly relevant. Property-management integrations require stack-specific validation.', [('Lead handoffs','Capture inquiries, assign owners, and track next steps.'),('Owner updates','Prepare reporting with defined metrics and review.'),('Team coordination','Document onboarding, vendor follow-up, and exceptions.')],'/case-studies/yokly-onboarding','https://www.appfolio.com/blog/naa-top-challenges-2026'),
 ('education','Education and training organizations','Bring structure to people and programs.','My school leadership experience informs this work. Each organization keeps its own policies and decision authority.', [('People operations','Coordinate recruitment, onboarding, and staff communication.'),('Leadership reporting','Bring priorities, owners, and unresolved actions into one view.'),('Content operations','Organize reviewed materials and recurring communication.')],'/case-studies/edgyvis-people-ops','https://apply.workable.com/j/7F192534DF'),
 ('professional-services','Accounting and professional services','Keep recurring client work on track.','This is a transferable application of my operations experience. I do not claim accounting or regulated advisory expertise.', [('Client onboarding','Track missing inputs, responsibilities, and next steps.'),('Executive support','Prepare correspondence, meetings, and action records.'),('Reviewable reporting','Draft updates from approved source information.')],'/case-studies/content-routing','https://careers.toaglobal.com/job-view/pr008101/')]
for slug,label,headline,intro,needs,case,source in industries:
 page('/industries/'+slug,label,intro,hero('Industry focus · '+label,headline,intro)+section('Recurring work worth improving',cards([(t,p,'/ai-sprint','Discuss this process') for t,p in needs]))+section('Experience and relevant demand','<p><a class="text-link" href="'+case+'">Explore relevant work →</a></p><p><a class="text-link" href="'+source+'" rel="noopener">Read an industry or hiring source →</a></p><p>A source illustrates operational needs. It does not establish every employer’s budget or financial stability.</p>')+section('Start with one useful decision','<p>Bring one process, your current tools, and the result you need.</p>'+cta()))
page('/industries','Industries','Real estate first, with education and professional-services applications.',hero('Industry focus','Operations shaped around your business.','Real estate is the primary focus. Education reflects direct experience; professional services applies transferable capabilities.')+section('Explore relevant business contexts',cards([(x[1],x[3],'/industries/'+x[0],'Explore this industry') for x in industries])))
page('/contact','Contact','Discuss employment or a scoped operations project.',hero('Work together','Choose the conversation you need.','Employment and consulting have different responsibilities, timelines, and payment arrangements.')+section('Two ways to work together',cards([('Hire for a role','Discuss responsibilities, working hours, and compensation.','mailto:'+EMAIL+'?subject=Employment%20inquiry','Email about employment'),('Discuss a project','Start with one recurring process and the result you need.','/ai-sprint#fit-check','Check project fit')]))+section('Helpful details for your inquiry',list_(['Company and website.','Role or recurring process.','Current tools and approximate workload.','Desired timing and approval contact.','Working hours for employment; budget range for projects.'])+'<p>Please leave credentials, client documents, and sensitive personal information out of your initial message.</p>'))
fit='''<form id="fit-form" class="fit-form">
<label for="process">Recurring process</label><select id="process" name="process" required><option value="">Choose a process</option><option value="lead-to-booked-call">Lead handoff</option><option value="weekly-report">Executive reporting</option><option value="content-routing">Approved content</option><option value="inbox-triage">Inbox support</option><option value="other">Another process</option></select>
<label for="frequency">How frequently it happens</label><select id="frequency" name="frequency" required><option value="">Choose frequency</option><option value="occasional">Occasionally</option><option value="weekly">Weekly</option><option value="daily">Daily</option></select>
<label for="systems">Systems involved</label><select id="systems" name="systems" required><option value="">Choose the closest fit</option><option value="supported">Only tools in the matching starter example</option><option value="custom">A different tool or custom integration</option><option value="unknown">Not sure yet</option></select>
<label for="examples">Representative examples available</label><select id="examples" name="examples" required><option value="">Choose availability</option><option value="yes">Yes, sanitized examples</option><option value="no">Not yet</option></select>
<label for="actions">What the workflow would do</label><select id="actions" name="actions" required><option value="">Choose action type</option><option value="draft">Draft information for review</option><option value="write">Send, book, or change records</option></select>
<button class="btn btn-primary" type="submit">Find a suitable next step</button></form>
<div id="fit-result" class="result-box" tabindex="-1" aria-live="polite" hidden></div>
<p class="fine-print">Answers stay in this browser. This suggests a starting point, not a quote or feasibility decision.</p>
<noscript><p>The interactive check needs JavaScript. You can still email a short description of your process.</p></noscript>
<a class="btn" data-sprint-inquiry href="mailto:ciarramazaredo@gmail.com?subject=Workflow%20fit%20inquiry">Email a workflow inquiry</a>'''
body=hero('Custom AI workflows','Know what to automate next.','Bring one recurring process. I map the work, examine exceptions, and investigate its biggest uncertainty.','<p class="price"><strong>US$750</strong> pilot price · Five business days after complete inputs</p><p class="sub">You receive a practical implementation brief. Use it with your team or a provider of your choice.</p><div class="actions"><a class="btn btn-primary" href="#fit-check">Check project fit</a><a class="btn" href="/workflows">Explore free workflows</a></div>')
body+=section('Start with a recurring bottleneck',cards([('Leads lose their owner','Inquiries move between forms, inboxes, calendars, and CRM records.','/workflows#lead-to-booked-call','Explore lead handoffs'),('Reporting takes repeated effort','Leaders need dependable numbers and visible exceptions.','/workflows#weekly-report','Explore reporting'),('Work depends on chasing people','Inputs, approvals, and next steps need clear ownership.','/case-studies/content-routing','Explore content operations')]))
body+=section('What your fixed fee includes',list_(['One process, up to three systems, and two stakeholders.','A 60-minute kickoff and review of up to 20 sanitized examples.','A current-state map with owners, exceptions, and workarounds.','Up to two hours investigating one technical uncertainty.','A recommendation: build, simplify, use an existing tool, or wait.','An implementation brief with approvals, acceptance tests, and recovery steps.','Operating-cost estimates with assumptions shown.','A 45-minute review and one factual-correction round requested within seven days.'])+'<p>Production implementation, migration, bulk cleanup, subscriptions, and ongoing support are separate.</p><p>A blocked feasibility check remains useful when it explains the evidence, limitations, and next step.</p>')
body+=section('See what you would receive',cards([('Sample assessment','A fictional property-reporting example shows the decision and handover format.','/sample-assessment','Read the sample'),('Inspect the workflow evidence','Examples distinguish offline checks from connected testing and operational use.','/workflows','Review the evidence')]))
body+=section('A focused five-day working process','<ol class="plain-list"><li><strong>Before day one:</strong> agree scope and payment; provide complete inputs.</li><li><strong>Day one:</strong> kickoff and map the current process.</li><li><strong>Days two and three:</strong> review examples and investigate the agreed uncertainty.</li><li><strong>Day four:</strong> prepare the recommendation, costs, and implementation brief.</li><li><strong>Day five:</strong> review findings and hand over the brief.</li></ol><p>Missing inputs pause the schedule. After five business days awaiting inputs, we rebook at the next available slot.</p>')
body+=section('Clear scope and continued ownership',list_(['Your accounts, data, and credentials stay yours.','The assessment is usable without purchasing implementation.','Background tools and third-party licenses are identified in the agreement.','No automatic implementation credit, guaranteed savings, or unlimited revisions.','The written scope confirms the total fee and applicable taxes before payment.','Cancellation settles completed work and approved nonrecoverable costs; unearned balances are returned.','A fifteen-minute fit call establishes suitability. Custom analysis belongs in the paid assessment.']))
body+=section('Choose the smallest useful engagement','<details><summary>When a free starter is enough</summary><p>Use an example when its process fits and you can configure and test it yourself.</p></details><details><summary>When you already know the build</summary><p>Request a setup or implementation quote. A paid assessment is not mandatory for clearly understood work.</p></details><details><summary>When the right answer is uncertain</summary><p>The sprint investigates one process before you commit to production work.</p></details><details><summary>How additional requests are handled</summary><p>We agree the additional scope, price, and timing before work begins.</p></details><details><summary>What happens after the sprint</summary><p>Implement independently, request a separate build quote, or decide not to automate.</p></details>')
body+=section('Check your project’s starting point',fit,'fit-check')
page('/ai-sprint','Workflow Fit & Feasibility Sprint','A US$750 pilot assessment for one recurring process. Written recommendation, bounded investigation, and an optional implementation path.',body)
page('/sample-assessment','Sample workflow assessment','Fictional property-reporting assessment showing scope, decision, and acceptance criteria.',hero('Illustrative deliverable · Fictional data','One process, a documented decision.','Example only. This is not a client engagement, completed paid sprint, or measured business result.')+section('The process and current problem','<p>A fictional property team prepares a weekly owner update from a shared KPI sheet.</p><p>Metrics can be missing, duplicated, or entered as text. The manager checks the report before distribution.</p>')+section('Recommendation and implementation boundary','<p>Start with deterministic data validation and a reviewable report draft.</p><p>Keep distribution with the manager. Consider AI-written summaries only after the numbers pass validation.</p>'+list_(['One KPI sheet, one draft destination, one reviewer.','No tenant screening, payment actions, or automatic owner distribution.','Missing metrics are visible; invalid values stop the report.','API access and delivery require a separate connected test.']))+section('Acceptance cases and recovery steps','<div class="table-wrap"><table><caption>Illustrative acceptance checklist</caption><thead><tr><th>Case</th><th>Expected result</th></tr></thead><tbody><tr><td>Only one week exists</td><td>Show current values; no invented comparison.</td></tr><tr><td>A metric is missing</td><td>Label missing data for review.</td></tr><tr><td>Duplicate or invalid values</td><td>Stop and notify the designated owner.</td></tr><tr><td>Draft delivery fails</td><td>Escalate; use the manual reporting procedure.</td></tr><tr><td>Manager approves</td><td>The manager sends the final update.</td></tr></tbody></table></div>')+section('Costs and unresolved questions','<p>Confirm current software plans, API access, report volume, and review effort before estimating costs.</p><p>Capacity recovery must subtract review, exception handling, and maintenance. No savings are asserted in this example.</p><p>Next decision: verify access and agree a separately priced implementation scope.</p><a class="btn btn-primary" href="/ai-sprint#fit-check">Check project fit</a>'))
print('Generated role, industry, contact, sprint and sample pages')
# Static case-study routes keep every case readable without JavaScript.
import json,subprocess
case_data=json.loads(subprocess.check_output(['node','-e',"global.window={};require('./assets/case-studies.js');process.stdout.write(JSON.stringify(window.CASE_STUDIES))"],cwd=ROOT))
for case in case_data:
 body=hero(case['clientType'],case['title'],case['headlineLabel'])
 for title,key in [('The context behind the work','about'),('The problem to work through','problem'),('My contribution to the work','move'),('The result and its limits','result'),('AI assistance and human judgment','ai'),('Human review and operating responsibility','human'),('What the evidence can support','evidence')]:
  body+=section(title,'<p>'+case.get(key,'Not documented.')+'</p>')
 body+=section('Sources and related next steps','<ul class="plain-list">'+''.join(f'<li><a class="text-link" href="{x["url"]}">{x["label"]}</a></li>' for x in case['sources'])+'</ul>'+cta())
 page('/case-studies/'+case['id'],case['title'],re.sub('<[^>]+>','',case['problem']),body)

page('/ai-notes','Applied AI workflow notes','Dated experiments, tested behavior and limits.',hero('Applied learning','Test the workflow before the claim.','I review new tools through practical experiments. These notes record completed checks and their limits.')+section('Reporting reliability before AI summaries','<p>16 November 2026 · Node 24 · Offline component experiment</p><p>A reporting calculator failed with one week of data or missing current metrics.</p><p>I separated deterministic validation from the AI summary and added explicit missing-data states.</p>'+list_(['Single-week data keeps current values without inventing previous results.','Missing current metrics stay visible instead of becoming zero.','Invalid numbers, dates, and duplicate records stop calculation.','Execution and trigger errors retain useful context without requiring a run URL.'])+'<p>Seven reporting and error-normalization tests pass. Connected n8n import, model output, and notification delivery remain unverified.</p><p>Adoption decision: validate numbers before asking AI to explain them.</p><a class="text-link" href="https://github.com/tinceus/ciarramazaredo/tree/main/workflows/weekly-report-error-alerts">Inspect source, fixtures and tests →</a>')+section('How I evaluate another tool','<p>Start with a business problem, representative inputs, costs, and a clear acceptance test.</p><p>Record versions, failures, review requirements, and the adoption decision. A simpler non-AI solution can be the right result.</p><p>Tool popularity is not evidence of my implementation expertise.</p><a class="btn" href="/workflows">Explore tested components</a>'))
